    public static AdListEntry? Find(string url) =>
        Array.Find(All, e => string.Equals(e.Url, url, StringComparison.OrdinalIgnoreCase));

    public static IEnumerable<string> Categories()
    {
        var seen = new List<string>();
        foreach (var e in All) if (!seen.Contains(e.Category)) seen.Add(e.Category);
        return seen;
    }

    public static IEnumerable<string> Hosts()
    {
        var hosts = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var e in All)
            try { hosts.Add(new Uri(e.Url).Host); } catch { }
        return hosts;
    }
